#include <iostream>
using namespace std;
int main() {
    cout << "1 to 5" << endl;
    int n = 1;
    while (n <= 5) {
        cout << n << endl;
        n = n + 1;
    }
    cout << "odd: add 2" << endl;
    int odd = 1;
    while (odd <= 9) {
        cout << odd << endl;
        odd = odd + 2;
    }
    cout << "odd: 2i-1" << endl;
    int i = 1;
    while (i <= 5) {
        cout << 2 * i - 1 << endl;
        i = i + 1;
    }
    return 0;
}
